import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import * as projectRepo from "@/server/repositories/project-repository";
import * as pmRepo from "@/server/repositories/project-member-repository";
import * as issueService from "@/server/services/issue-service";
import * as commentService from "@/server/services/comment-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import { NotFoundError } from "@/server/services/_support";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
describe("private", () => {
  it("works", async () => {
    const t = await createTenant("privt", "pro");
    const pid = t.project.id;
    const issue = await issueService.createIssue(t.actors.admin, issueInput(t.org.id, pid));
    await projectRepo.updateProject({ orgId: t.org.id, projectId: pid, visibility: "private" } as never);
    const m = t.actors.member;
    await expect(issueService.getIssue(m, t.org.id, issue.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(issueService.getBoard(m, t.org.id, pid)).rejects.toBeInstanceOf(NotFoundError);
    await expect(commentService.getThread(m, t.org.id, issue.id)).rejects.toBeInstanceOf(NotFoundError);
    expect((await issueService.listIssues(m, { orgId: t.org.id, limit: 50, cursor: null } as never)).total).toBe(0);
    expect((await issueService.listIssues(t.actors.admin, { orgId: t.org.id, limit: 50, cursor: null } as never)).total).toBe(1);
    const pl = await projectService.listProjects(m, { orgId: t.org.id, limit: 50, cursor: null } as never);
    expect(pl.items.length).toBe(0); expect(pl.total).toBe(0);
    await pmRepo.addProjectMember(t.org.id, pid, m.userId);
    expect((await issueService.listIssues(m, { orgId: t.org.id, limit: 50, cursor: null } as never)).total).toBe(1);
    expect((await projectService.listProjects(m, { orgId: t.org.id, limit: 50, cursor: null } as never)).total).toBe(1);
    await issueService.getIssue(m, t.org.id, issue.id);
  });
});
EOF
